from collections import deque

def transform(grid):
    if not grid: return grid
    rows, cols = len(grid), len(grid[0])

    # Background is the most frequent color
    bg = grid[0][0]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 4:
                bg = grid[r][c]
                break
        else:
            break

    visited = [[False]*cols for _ in range(rows)]
    objects = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and not visited[r][c]:
                cr, cc = [], []
                color = grid[r][c]
                q = deque([(r,c)])
                visited[r][c] = True

                while q:
                    curr_r, curr_c = q.popleft()
                    cr.append(curr_r)
                    cc.append(curr_c)

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                min_r, max_r = min(cr), max(cr)
                min_c, max_c = min(cc), max(cc)
                w, h = max_c - min_c + 1, max_r - min_r + 1

                # Frame rule: if either dimension > 4, frame with 3, otherwise 1
                if w > 4 or h > 4:
                    frame_color = 3
                else:
                    frame_color = 1

                objects.append((min_r, max_r, min_c, max_c, w, h, frame_color))

    out = [row[:] for row in grid]

    for (min_r, max_r, min_c, max_c, w, h, frame_color) in objects:
        for r in range(max(0, min_r - 1), min(rows, max_r + 2)):
            for c in range(max(0, min_c - 1), min(cols, max_c + 2)):
                if min_r <= r <= max_r and min_c <= c <= max_c:
                    # Inside object: keep original color
                    out[r][c] = grid[r][c]
                elif grid[r][c] == bg:
                    out[r][c] = frame_color

    return out
